# Generate every numerical table in the Phase C report from the descriptive outputs.
source("Scripts/Congestion/descriptive_helpers.R")
x <- readRDS(file.path(out, "descriptive_summary.rds"))
s <- readRDS(file.path(out, "group_series.rds"))
cells <- readRDS(file.path(out, "cell_eligibility.rds"))
dec <- readRDS(file.path(out, "rest_decomposition.rds"))
manifest <- readRDS("Data/Waze/parquet/deduplication_manifest.rds")
getv <- function(g, dt, v, b = "Peak") s[series == g & date == dt & block == b, get(v)]
facts <- data.table(metric = c("retained_cells", "never_observed", "observed_no_pre", "rest_retained", "saturated20", "threshold12",
  "center_cells", "belisario_cells", "corridor_cells", "ring_cells", "allroad_keys", "large_keys", "negative_spread_keys", "gap_negative_keys"),
  value = c(sum(cells$eligible),sum(cells$never_observed),sum(!cells$never_observed & cells$no_pre),
    cells[group == "REST",sum(eligible)],sum(cells$saturated),cells[group == "REST" & eligible == TRUE,sum(pre_slots >= 12)],
    x$exclusions[group == "CENTER",retained],x$exclusions[group == "BELISARIO",retained],
    x$exclusions[group == "CORRIDOR",retained],x$exclusions[group == "RING",retained],
    manifest$proof$distinct_rows[manifest$proof$roadtype == "all_roadtype"],
    manifest$proof$distinct_rows[manifest$proof$roadtype == "large"],x$flagged_total,x$flagged_gap))
for (g in c("CENTER","BELISARIO","REST","REST_saturated")) {
  for (v in c("tci_osm_ratio","presence","tc_spread")) facts <- rbind(facts,
    data.table(metric = paste(g,"202311",v,sep = ":"),value = getv(g,202311,v)))
}
saveRDS(facts, file.path(out,"report_numeric_facts.rds"))
{
  status <- system2(file.path(R.home("bin"),"Rscript"), "Scripts/Congestion/02_audit_descriptives.R")
  stopifnot(status == 0)
}
audit <- readRDS(file.path(out,"independent_audit.rds"))
stopifnot(all(audit$match))
period <- copy(s[block == "Peak" & ((date >= 202201 & date <= 202311) | (date >= 202501 & !date %in% gap))])
period[, period := fifelse(date <= 202212,"2022",fifelse(date <= 202311,"Jan-Nov 2023","Usable 2025"))]
period <- period[, .(TCI = mean(tci_osm_ratio), presence = mean(presence), TCS_metres = mean(tc_spread),
  conditional_TCI = sum(tci_osm_ratio) / sum(presence)), by = .(series,period)]
saveRDS(period,file.path(out,"period_descriptive_levels.rds"))
pv <- function(g,v) period[series == g,get(v)]
fig <- function(name, caption) c(paste0("![",caption,"](../Output/Waze/descriptives/",name,".png)"), "")
lines <- c("# Waze descriptives and pre-period diagnostics", "", "Date: 2026-09-17. Phase C. No post-opening treatment effect has been estimated.", "",
  "## Reproduction and fixed conventions", "",
  "From the repository root run `Rscript Scripts/Congestion/02_prepare_blocks.R` once, then `Rscript Scripts/Congestion/02_descriptives.R` and `Rscript Scripts/Congestion/02_report.R`. The last command launches the independent audit in a fresh R session. For a new audit after regeneration, run `02_audit_descriptives.R` explicitly and then `02_report.R` again. Only the preparation script reads the raw Parquet. It verifies unique keys, writes the distinct all_roadtype and large blocks to Data/Waze/parquet/, and preserves raw_multiplicity as provenance. Repeated preparation reuses the files. The CSV is not read again. All subsequent Waze reads use those two blocks; the validated Phase B spatial metadata and original GPKG layers supply geography.", "",
  "All congestion series use all_roadtype. Morning means bins 7 and 8, evening 17 and 18, and night 0 through 4. Peak pools the four morning/evening bins with equal weights. There is no day-of-week field, so weekends remain in every block. Each retained cell receives equal weight in each month. The all-road/fast-road support comparison is a diagnostic of two separately filtered blocks, never their sum. large means free-flow speed above 50 km/h, not an arterial road class.", "",
  "The completed panel sets absent records to zero for primary TCI, severe TCI and TCS metres, but never imputes jam speed or free flow. Exact -998/-999 sentinels become NA. Neither a missing flag_corr_type nor missing user/jam counts can be reconstructed. Jam speed first averages available hourly records within each cell, then gives equal weight to cells with a defined average; its changing support appears below. It is conditional on recorded congestion, not an unconditional speed outcome. Free flow appears only as a diagnostic, not as a fifth outcome.", "",
  "Every cell has NA outcomes in February, March and April 2025. No line or average fills the gap. Usable P2 consists of January and May-December 2025, nine months. P1 remains December 2023-August 2024; disruption remains all of September-December 2024. Time-series plots mark the opening and shade disruption grey and the delivery gap amber. Pre-only panels explicitly end before these dates; maps, scatterplots and hour profiles have no calendar axis to shade.", "",
  "## Fixed population and donor coverage", "",
  "The no-pre column includes never-observed cells; the observed-but-no-pre column counts the additional exclusion after dropping never-observed cells. Eligibility is fixed for every month. Pre coverage divides delivered all-road hour slots by all 23 months from January 2022 through November 2023, counting absent slots as zero. Saturated donors require at least 20 slots per month; threshold 12 is a sensitivity option. This is profile availability, not a count of users or underlying hourly timestamps.", "",md_table(x$exclusions),"",
  sprintf("All 740 never-observed cells lie in REST. A further %d observed REST cells have no pre-period record. The resulting population contains %d cells, including %d REST cells and %d saturated donors; threshold 12 retains %d REST cells. No monitor-neighborhood, CORRIDOR or RING cell is lost.",
    sum(!cells$never_observed & cells$no_pre),sum(cells$eligible),cells[group=="REST",sum(eligible)],sum(cells$saturated),cells[group=="REST" & eligible==TRUE,sum(pre_slots>=12)]), "",
  "CENTER and BELISARIO are the published-point seed plus six H3 neighbors. Coordinates rounded to 0.01 degrees do not establish the true monitor cell. This replaces the requested single-cell series until precise coordinates arrive. Remaining cells within 1 km of any station form CORRIDOR; those within 2 km form RING; the rest form REST. Neighborhoods take priority. Distances use delivered centroids. MetroStations.gpkg supplies stations, MetroLine.gpkg the alignment, and Distancia_REMMAQ_Metro.gpkg the rounded monitor points, all copied from the air-quality repository. The original San Francisco buffer remains an alternative, not the adopted CENTER geometry.", "",md_table(x$neighborhoods),"",
  fig("map_groups","Provisional groups and excluded geometry"),fig("map_density","Pre-period data density"),fig("map_saturated_donors","Saturated REST donors"),
  "## Singleton-key concentration", "",
  "The following single table compares the two cleaned blocks. Categories are cells, delivered months or hours. The top five percent means ceiling(0.05 times category count), ranked by singleton count, not selected by outcomes. Compare their share of singletons with their share of all keys. Singleton minima/maxima describe within-category proportions. Exact duplicates cannot be treated as independent observations or allowed to reweight groups.", "",md_table(x$singleton),"",
  "Singletons concentrate entirely by cell, not by date or hour. All-road singleton cells have multiplicity one at every delivered key; the other cells have multiplicity three. Month and hour singleton shares stay near 14 percent. This is consistent with a spatial duplication mechanism, whose provenance remains unconfirmed. Deduplication removes the resulting geographic reweighting.", "",
  "## Raw outcome trajectories and reporting proxies", "",
  fig("series_tci_osm_ratio","Primary outcome by group and hour block"),fig("series_tci_severe_osm_ratio","Severe congestion by group and hour block"),
  fig("series_avg_jam_speed_ratio","Record-conditional jam speed by group and hour block"),fig("series_tc_spread","TCS spread in metres"),
  fig("monitor_neighborhoods","The two seven-cell monitor neighborhoods"),
  "These panels are delivered/completed levels, not counterfactual comparisons. The two REST lines always use the same exclusions; the saturated line additionally applies the pre-only threshold. The next table gives equal-month descriptive levels. January-November 2023 deliberately excludes opening month. Usable 2025 excludes the entire delivery gap. Differences between rows must not be read as metro effects.", "",md_table(period),"",
  fig("penetration_proxies","Presence and TCS as indirect proxies"),
  "Actual observation and jam-event counts were not delivered. Presence records whether any monthly hour-profile row exists; TCS measures delivered spread in metres. Both combine traffic and Waze reporting. They cannot distinguish app penetration from genuine changes in congestion. CENTER is much more saturated than the broad REST pool, so a common penetration trend is not a defensible default.", "",
  fig("rest_decomposition","REST peak presence-intensity decomposition"),
  "For primary TCI, the completed equal-cell/equal-hour average equals presence times intensity conditional on a record. Conditional intensity here pools recorded cell-hours, which is required for the identity; it is not an equal-cell average of conditional means. Both margins can move. The decomposition diagnoses the source of changes in the delivered series, not the cause of reporting or traffic changes. rest_decomposition.rds retains monthly morning, evening and combined-peak values for both REST populations.", "",
  sprintf("In the broad REST pool, peak presence is %s in 2022, January-November 2023 and usable 2025, respectively; conditional TCI is %s percent. Both margins contribute to its rising delivered level. Saturated REST presence is %s, while conditional TCI is %s percent. Its trajectory is therefore mainly an intensity change, not increasing record presence. Neither statement identifies traffic separately from changes in the provider's measurements.",paste(fmt(pv("REST","presence")),collapse=", "),paste(fmt(pv("REST","conditional_TCI")),collapse=", "),paste(fmt(pv("REST_saturated","presence")),collapse=", "),paste(fmt(pv("REST_saturated","conditional_TCI")),collapse=", ")), "",
  fig("hour_profiles","Pre-opening and usable-2025 hour profiles"),
  "The pre profile pools January 2022-November 2023, not all of calendar 2023. The second panel pools only usable 2025 months. Both use equal cell-month weights. A different seasonal mix and missing weekday information limit interpretation. The profiles are not differenced and do not estimate a treatment effect.", "",
  "## Free flow, composition and artifacts", "",fig("freeflow_diagnostic","Free-flow diagnostic"),
  "TCI/OSM divides by OSM road length and the provider's expected observation normalization, not by free-flow speed. Monthly free-flow estimation still affects jam detection, the severe threshold, speed ratios and speed-class membership. This plot conditions on delivered records and cannot hold the underlying segment mix fixed. The following levels bracket opening and disruption without estimating a break or attributing a change to either event.", "",md_table(x$freeflow_levels),"",
  sprintf("CENTER free flow is %s km/h in November 2023, December 2023, August 2024 and September 2024, respectively. Other comparators do not all move together, and CENTER is volatile well before opening. These are visible local discontinuities, not formal break tests. The figures do not support dismissing the monthly free-flow threat or claiming a unique metro-timed break.",paste(fmt(x$freeflow_levels[series=="CENTER",avg_freeflow]),collapse=", ")), "",
  fig("fast_road_support","Fast-road versus all-road support"),
  "The fast/all support ratio describes available speed-class profiles. It is not a road-length share or a functional road composition measure. The two deduplicated blocks cannot reconstruct all six original class trajectories; Phase B retains their inventory. Monthly speed reclassification and reporting changes can both alter this proxy. Ask for fixed segment classes and denominators before using fast roads as a confirmatory restriction.", "",
  sprintf("A new delivery inconsistency complicates this check: %d fast-road keys across %d cells have no all_roadtype key at the same cell-month-hour. Consequently the fast/all support ratio can exceed one, as it does in Belisario in November 2023. This contradicts simple nesting of the delivered row supports. The descriptive all-road completion rule remains as instructed, but the provider must explain whether these missing all-road records really mean zero congestion.", x$fast_orphans$fast_keys_without_allroad,x$fast_orphans$cells), "",
  fig("construction_preperiod","Pre-opening construction-period inspection"),
  "The full-period primary and proxy panels also document the pronounced 2020 trough and subsequent recovery. Construction-period plots show the delivered 2022-2023 trajectories only. No dated San Francisco/La Alameda closure or reopening log was supplied, so the series cannot establish which local movements reflect construction teardown. Keep that mechanism as unresolved, not as a verified artifact with an assigned date.", "",
  "## Negative auxiliary spread-ratio rows", "",
  sprintf("The distinct all-road block contains %d negative tc_spread_osm_ratio rows after excluding exact sentinels. %d fall in the masked delivery gap. %d flagged rows have two usable adjacent calendar months on the retained population. The comparison uses the same cell and hour, completes genuinely absent neighboring records with zero, and requires both adjacent months. It does not substitute the nearest available month across a gap. The reference distribution comprises unflagged delivered rows with the same two-neighbor requirement; it is not matched on traffic level.",x$flagged_total,x$flagged_gap,x$flagged_comparable),"",
  md_table(x$anomaly_summary),"",md_table(x$bad_groups),"",md_table(x$matched_anomalies),"",
  sprintf("All flagged keys belong to REST. Among two-neighbor comparisons, their median primary TCI is %.4f percent versus an adjacent-month median of %.4f; the median signed deviation is %+.4f percentage points. Unflagged rows have a much smaller median deviation, %+.4f. The additional table compares scaled absolute deviations against unflagged months in the same cell-hour, reducing the concern that the global reference simply has lower congestion. These unusually elevated values look potentially contaminated; the comparison cannot establish whether the error lies in the primary field, the auxiliary field, or both. Treat this as a donor-quality threat rather than declaring the primary outcome clean.",x$anomaly_summary[bad_spread==TRUE,median_tci],x$anomaly_summary[bad_spread==TRUE,median_adjacent],x$anomaly_summary[bad_spread==TRUE,median_deviation],x$anomaly_summary[bad_spread==FALSE,median_deviation]), "",
  fig("negative_spread_timing","Timing of auxiliary-ratio problems"),fig("negative_spread_comparison","Primary TCI against adjacent months"),
  "The original negative auxiliary field is not an analysis outcome. This diagnostic can reveal accompanying primary-TCI anomalies but cannot certify the primary numerator or OSM denominator. Keep the flagged keys in the primary descriptive series, label them, and ask the provider to trace the error before choosing a treatment-analysis exclusion rule. The complete flagged-row comparison is negative_spread_adjacent_months.rds.", "",
  "## Pre-period summaries and donor diagnostics", "",
  "The table describes equally weighted cell-month block averages from January 2022 through November 2023. SD is across cell-months, not a standard error. Zero-congestion share always means the share with primary TCI equal to zero, including for the conditional speed outcome; it does not mean zero vehicle speed. Defined cell-months records the different speed support. Ratio units are percentage points and TCS units are metres.", "",md_table(x$pre_summary),"",
  "The correlations below compare 23 monthly combined-peak means in levels, without detrending or fitting synthetic controls. CORRIDOR and RING are diagnostic comparators only; their possible exposure makes them unsuitable confirmatory donors under the current buffer rule.","",md_table(x$correlations),"",fig("pre_donor_comparison","Pre-only target and comparator means"),
  "More donor cells do not create more independent pre-period months or eliminate spatial dependence. High correlation alone does not establish counterfactual validity, while level mismatch and held-out prediction error remain design concerns.", "",
  "## Conditional speed denominators", "",md_table(x$jam_speed_support),"",
  "## Numeric ledger and independent hostile-review audit", "",
  "This ledger exposes numerical claims for reproducibility. The audit draws ten entries without replacement from this fixed ledger with seed 20260918, then recomputes them in a fresh R process from the deduplicated source blocks using independent DuckDB queries. It does not read the completed panel, group-series objects, or report-generation calculations. The accepted Phase B audit already checked original raw counts; this audit follows the author's new clean-block-only rule.", "",md_table(facts),"",md_table(audit),"",
  "All ten regenerated values match at tolerance 1e-9 times max(1, absolute reported value). No mismatch remains. This is a spot audit, not proof against every aggregation error. Scripts also assert the missing-month mask and unique cleaned keys. No post-opening regression, ATT, event-study coefficient, synthetic-control fit or SDID fit was computed.", "")
while (length(lines) && tail(lines,1)=="") lines <- head(lines,-1)
writeLines(lines,"reports/waze_descriptives.md")
message("Wrote reports/waze_descriptives.md")
